document.addEventListener("DOMContentLoaded", () => {
    // Ripple
    const createRipple = (event) => {
        const button = event.currentTarget;
        const circle = document.createElement("span");
        const diameter = Math.max(button.clientWidth, button.clientHeight);
        const radius = diameter / 2;
        circle.style.width = circle.style.height = `${diameter}px`;
        circle.style.left = `${event.clientX - button.getBoundingClientRect().left - radius}px`;
        circle.style.top = `${event.clientY - button.getBoundingClientRect().top - radius}px`;
        circle.classList.add("ripple");
        const existingRipple = button.getElementsByClassName("ripple")[0];
        if (existingRipple) { existingRipple.remove(); }
        button.appendChild(circle);
    };
    document.querySelectorAll(".btn, .SideNav-item, .LabelName, .circle").forEach((btn) => {
        btn.addEventListener("click", createRipple);
        const style = window.getComputedStyle(btn);
        if (style.position === 'static') { btn.style.position = "relative"; }
        if (style.overflow !== 'hidden') { btn.style.overflow = "hidden"; }
    });

    // Animation
    document.querySelectorAll('.SideNav-item').forEach((el, i) => {
        el.style.animationDelay = `${i * 0.05}s`;
        el.classList.add('fade-in');
    });

    // Back to Top FAB
    let fab = document.createElement('button');
    fab.className = 'fab-btn';
    fab.innerHTML = '<svg class="octicon" width="24" height="24" viewBox="0 0 16 16" fill="currentColor"><path d="M8 3.5a.5.5 0 0 1 .5.5v9a.5.5 0 0 1-1 0V4a.5.5 0 0 1 .5-.5z"/><path d="M4.646 6.854a.5.5 0 0 1 .708 0L8 4.207l2.646 2.647a.5.5 0 0 1-.708.708L8 5.707 5.354 8.354a.5.5 0 0 1-.708-.708z"/></svg>';
    fab.onclick = () => window.scrollTo({ top: 0, behavior: 'smooth' });
    document.body.appendChild(fab);

    window.onscroll = () => {
        if (document.body.scrollTop > 100 || document.documentElement.scrollTop > 100) {
            fab.style.display = "flex";
        }
        else {
            fab.style.display = "none";
        }
    };
});

